#!/usr/bin/env python3
"""Packs tools/lottie/json/*.json into LottieData.java (a System UI process cannot read this module's resources)."""
import os, sys
here = os.path.dirname(os.path.abspath(__file__))
out = os.path.join(here, '..', '..', 'app/src/main/java/dev/android/dynamicisland/island/graphics/LottieData.java')
CHUNK = 12000
lines = ['package dev.android.dynamicisland.island.graphics;', '',
         '/** Generated by tools/lottie/embed.py from tools/lottie/json; do not edit. */',
         'final class LottieData {', '    private LottieData() {', '    }', '',
         '    static String get(String name) {', '        switch (name) {']
body = []
for f in sorted(os.listdir(os.path.join(here, 'json'))):
    name = f[:-5]
    s = open(os.path.join(here, 'json', f), encoding='utf-8').read()
    parts = [s[i:i + CHUNK] for i in range(0, len(s), CHUNK)]
    esc = lambda t: t.replace('\\', '\\\\').replace('"', '\\"')
    lines.append('            case "%s":' % name)
    lines.append('                return %s();' % ('d_' + name))
    body.append('    private static String d_%s() {' % name)
    body.append('        return ' + ('\n                + '.join('"%s"' % esc(p) for p in parts)) + ';')
    body.append('    }\n')
lines += ['            default:', '                return null;', '        }', '    }', ''] + body + ['}', '']
open(out, 'w', encoding='utf-8').write('\n'.join(lines))
print('wrote', os.path.normpath(out))
